actions.call:
navigate(`${routePrefix}/auth/otp`, {
          replace: true,
          state: {
            challengeId: challenge.id,
            method: challenge.method,
            maskedDestination: challenge.maskedDestination,
            expiresAt: challenge.expiresAt,
          },
        })

navigate('/w/auth/success', {
      replace: true,
      state: { purpose: 'register', from: '2fa-setup' },
    })

navigate(`${prefix}/auth/otp`, {
          replace: true,
          state: {
            challengeId: challenge.id,
            method: challenge.method,
            maskedDestination: challenge.maskedDestination,
            expiresAt: challenge.expiresAt,
          },
        })

navigate('/w/auth/otp', {
        replace: true,
        state: {
          challengeId: challenge.id,
          method: challenge.method,
          maskedDestination: challenge.maskedDestination,
          expiresAt: challenge.expiresAt,
        },
      })

navigate(`${routePrefix}/trade/order-receipt`, {
      state: {
        order: {
          orderId: order.id,
          symbol: order.symbol,
          baseAsset: order.symbol.split('/')[0],
          side: order.side,
          orderType: order.type,
          price: order.price,
          amount: order.amount,
          total: order.price * order.amount,
          fee: order.fee,
          timestamp: order.createdAt,
          status: order.status,
        },
      },
    })

navigate(copyProviderFlowPath(location.pathname, prefix, provider.id, 'confirmation'), {
              state: {
                providerId: provider.id,
                capital,
                copyMode,
                positionSizing,
                copyRatio,
                customStopLoss: customStopLoss ? Number(customStopLoss) : undefined,
              },
            })
